body.script:
function toggleAccordion(n){var b=document.getElementById('body_'+n);var a=document.getElementById('arrow_'+n);b.classList.toggle('open');a.classList.toggle('open')}
function toggleSpcUser(n,val){var s=document.getElementById('sh_'+n+'_spc_search');var t=document.getElementById('sh_'+n+'_type_section');if(val==='yes'){s.classList.remove('hidden');t.classList.add('hidden')}else{s.classList.add('hidden');t.classList.remove('hidden')}}
function toggleShareholderType(n,val){var i=document.getElementById('sh_'+n+'_individual');var e=document.getElementById('sh_'+n+'_entity');if(val==='individual'){i.classList.remove('hidden');e.classList.add('hidden')}else{i.classList.add('hidden');e.classList.remove('hidden')}}
function toggleAltNat(n,val){var f=document.getElementById('sh_'+n+'_alt_nat_fields');val==='yes'?f.classList.remove('hidden'):f.classList.add('hidden')}
function toggleAltNatEnt(n,val){var f=document.getElementById('sh_'+n+'_ent_alt_nat_fields');val==='yes'?f.classList.remove('hidden'):f.classList.add('hidden')}
function toggleSecondary(n,val){var f=document.getElementById('sh_'+n+'_secondary_field');val==='yes'?f.classList.remove('hidden'):f.classList.add('hidden')}
function toggleSecondaryEnt(n,val){var f=document.getElementById('sh_'+n+'_ent_secondary_field');val==='yes'?f.classList.remove('hidden'):f.classList.add('hidden')}
function toggleUaeVisa(n,val){var f=document.getElementById('sh_'+n+'_uae_visa_fields');val==='yes'?f.classList.remove('hidden'):f.classList.add('hidden')}
function updateCount(el,id){document.getElementById(id).textContent=el.value.length+' / 150'}
function deleteShareholder(n){var a=document.getElementById('acc_'+n);if(a)a.remove()}
function saveShareholder(n){
    var b=document.querySelector('#acc_'+n+' .save-btn');
    if(b){b.textContent='✓ SAVED';b.style.background='#1abc9c';}
    // Collapse the accordion body
    var body=document.getElementById('body_'+n);
    var arrow=document.getElementById('arrow_'+n);
    if(body){body.classList.remove('open');}
    if(arrow){arrow.classList.remove('open');}
    // Update header to show saved state
    var header=document.querySelector('#acc_'+n+' .accordion-header span:first-child');
    if(header){header.textContent='Shareholder '+n+' ✓';}
}
function showClear(clearId,sel){var btn=document.getElementById(clearId);if(btn){sel.value?btn.classList.remove('hidden'):btn.classList.add('hidden')}}
function clearSelect(selId,clearId){var s=document.getElementById(selId);if(s)s.value='';var b=document.getElementById(clearId);if(b)b.classList.add('hidden')}
function toggleFlagMenu(n){var m=document.getElementById('sh_'+n+'_flag_menu');if(m)m.classList.toggle('hidden')}
function setFlag(n,flag,code,country){var btn=document.getElementById('sh_'+n+'_flag_btn');if(btn)btn.innerHTML=flag+' '+code+' &#9660;';var m=document.getElementById('sh_'+n+'_flag_menu');if(m)m.classList.add('hidden')}
document.addEventListener('click',function(e){document.querySelectorAll('[id$="_flag_menu"]').forEach(function(m){if(!m.classList.contains('hidden')&&!m.parentElement.contains(e.target)){m.classList.add('hidden')}})})

function buildShareholderHTML(i){
    var div = document.createElement('div');
    div.className = 'accordion';
    div.id = 'acc_' + i;
    div.innerHTML = '<div class="accordion-header" onclick="toggleAccordion('+i+')">' +
        '<span>Shareholder ' + i + '</span>' +
        '<span class="accordion-arrow open" id="arrow_'+i+'">&#9660;</span></div>' +
        '<div class="accordion-body open" id="body_'+i+'">' +
        '<div class="delete-btn" onclick="deleteShareholder('+i+')" style="color:#e53e3e;cursor:pointer;margin-bottom:16px;text-align:right">&#128465; Delete Shareholder</div>' +
        '<div style="margin-bottom:16px"><span style="font-size:13px;font-weight:600;color:#1a2340">Is the shareholder an existing SPC user?</span><br>' +
        '<label style="margin-right:16px;font-size:13px"><input type="radio" name="sh_'+i+'_spc_user" value="yes"/> Yes</label>' +
        '<label style="font-size:13px"><input type="radio" name="sh_'+i+'_spc_user" value="no" checked/> No</label></div>' +
        '<div style="margin-bottom:16px"><span style="font-size:13px;font-weight:600;color:#1a2340">Select shareholder type</span><br>' +
        '<label style="margin-right:16px;font-size:13px"><input type="radio" name="sh_'+i+'_type" value="individual" checked/> Individual</label>' +
        '<label style="font-size:13px"><input type="radio" name="sh_'+i+'_type" value="entity"/> Entity</label></div>' +
        '<div style="display:grid;grid-template-columns:1fr 1fr;gap:16px;margin-bottom:12px">' +
        '<div><label style="font-size:11px;color:#888;display:block;margin-bottom:4px">First name</label>' +
        '<input type="text" name="sh_'+i+'_first_name" style="width:100%;padding:10px 0;border:none;border-bottom:2px solid #e0e0e0;background:transparent;font-size:14px;outline:none"/></div>' +
        '<div><label style="font-size:11px;color:#888;display:block;margin-bottom:4px">Last name</label>' +
        '<input type="text" name="sh_'+i+'_last_name" style="width:100%;padding:10px 0;border:none;border-bottom:2px solid #e0e0e0;background:transparent;font-size:14px;outline:none"/></div></div>' +
        '<div style="margin-bottom:12px"><label style="font-size:11px;color:#888;display:block;margin-bottom:4px">Passport number</label>' +
        '<input type="text" name="sh_'+i+'_passport_no" style="width:100%;padding:10px 0;border:none;border-bottom:2px solid #e0e0e0;background:transparent;font-size:14px;outline:none"/></div>' +
        '<div style="margin-bottom:12px"><label style="font-size:11px;color:#888;display:block;margin-bottom:4px">Date of birth</label>' +
        '<input type="date" name="sh_'+i+'_dob" style="width:100%;padding:10px 0;border:none;border-bottom:2px solid #e0e0e0;background:transparent;font-size:14px;outline:none"/></div>' +
        '<div style="margin-bottom:12px"><label style="font-size:11px;color:#888;display:block;margin-bottom:4px">Nationality</label>' +
        '<select name="sh_'+i+'_nationality" style="width:100%;padding:10px 0;border:none;border-bottom:2px solid #e0e0e0;background:transparent;font-size:14px;outline:none">' +
        '<option value=""></option><option value="AE">United Arab Emirates</option><option value="IN">India</option>' +
        '<option value="PK">Pakistan</option><option value="GB">United Kingdom</option><option value="US">United States</option><option value="other">Other</option></select></div>' +
        '<div style="margin-bottom:12px"><label style="font-size:11px;color:#888;display:block;margin-bottom:4px">E-mail ID</label>' +
        '<input type="email" name="sh_'+i+'_email_id" style="width:100%;padding:10px 0;border:none;border-bottom:2px solid #e0e0e0;background:transparent;font-size:14px;outline:none"/></div>' +
        '<div style="margin-bottom:12px"><label style="font-size:11px;color:#888;display:block;margin-bottom:4px">Mobile number</label>' +
        '<input type="tel" name="sh_'+i+'_mobile" style="width:100%;padding:10px 0;border:none;border-bottom:2px solid #e0e0e0;background:transparent;font-size:14px;outline:none"/></div>' +
        '<div style="display:grid;grid-template-columns:1fr 1fr;gap:16px;margin-bottom:12px">' +
        '<div><label style="font-size:11px;color:#888;display:block;margin-bottom:4px">Shares allocated (%)</label>' +
        '<input type="number" name="sh_'+i+'_shares" style="width:100%;padding:10px 0;border:none;border-bottom:2px solid #e0e0e0;background:transparent;font-size:14px;outline:none"/></div>' +
        '<div><label style="font-size:11px;color:#888;display:block;margin-bottom:4px">Share value (AED)</label>' +
        '<input type="number" name="sh_'+i+'_share_value" style="width:100%;padding:10px 0;border:none;border-bottom:2px solid #e0e0e0;background:transparent;font-size:14px;outline:none"/></div></div>' +
        '<div style="text-align:right;margin-top:16px">' +
        '<button type="button" onclick="saveShareholder('+i+')" style="background:#1a2340;color:white;border:none;border-radius:8px;padding:10px 28px;font-size:14px;font-weight:600;cursor:pointer">SAVE</button></div>' +
        '</div>';
    return div;
}

function updateShareholderList(count){
    count=Math.min(Math.max(parseInt(count)||1,1),20);
    var list=document.getElementById('acc_1') ? document.getElementById('acc_1').parentElement : null;
    var existing=list.querySelectorAll('.accordion').length;
    if(count>existing){
        for(var i=existing+1;i<=count;i++){
            var div = document.createElement('div');
            div.className = 'accordion';
            div.id = 'acc_' + i;
            div.innerHTML = '<div class="accordion-header" onclick="toggleAccordion(' + i + ')"><span>Shareholder ' + i + '</span><span class="accordion-arrow" id="arrow_' + i + '">&#9660;</span></div>' +
                '<div class="accordion-body" id="body_' + i + '">' +
                '<div style="padding:16px">' +
                '<div style="margin-bottom:16px"><span style="font-size:13px;font-weight:600;color:#1a2340">Is the shareholder an existing SPC user?</span><br>' +
                '<label style="margin-right:16px;font-size:13px"><input type="radio" name="sh_' + i + '_spc_user" value="yes"/> Yes</label>' +
                '<label style="font-size:13px"><input type="radio" name="sh_' + i + '_spc_user" value="no" checked/> No</label></div>' +
                '<div style="margin-bottom:16px"><span style="font-size:13px;font-weight:600;color:#1a2340">Select shareholder type</span><br>' +
                '<label style="margin-right:16px;font-size:13px"><input type="radio" name="sh_' + i + '_type" value="individual" checked/> Individual</label>' +
                '<label style="font-size:13px"><input type="radio" name="sh_' + i + '_type" value="entity"/> Entity</label></div>' +
                '<div style="display:grid;grid-template-columns:1fr 1fr;gap:16px;margin-bottom:12px">' +
                '<div><label style="font-size:11px;color:#888;display:block">First name</label><input type="text" name="sh_' + i + '_first_name" style="width:100%;padding:8px 0;border:none;border-bottom:2px solid #e0e0e0;background:transparent;font-size:14px;outline:none"/></div>' +
                '<div><label style="font-size:11px;color:#888;display:block">Last name</label><input type="text" name="sh_' + i + '_last_name" style="width:100%;padding:8px 0;border:none;border-bottom:2px solid #e0e0e0;background:transparent;font-size:14px;outline:none"/></div></div>' +
                '<div style="margin-bottom:12px"><label style="font-size:11px;color:#888;display:block">Passport number</label><input type="text" name="sh_' + i + '_passport_no" style="width:100%;padding:8px 0;border:none;border-bottom:2px solid #e0e0e0;background:transparent;font-size:14px;outline:none"/></div>' +
                '<div style="margin-bottom:12px"><label style="font-size:11px;color:#888;display:block">Date of birth</label><input type="date" name="sh_' + i + '_dob" style="width:100%;padding:8px 0;border:none;border-bottom:2px solid #e0e0e0;background:transparent;font-size:14px;outline:none"/></div>' +
                '<div style="margin-bottom:12px"><label style="font-size:11px;color:#888;display:block">Nationality</label><select name="sh_' + i + '_nationality" style="width:100%;padding:8px 0;border:none;border-bottom:2px solid #e0e0e0;background:transparent;font-size:14px;outline:none"><option value=""></option><option value="AE">UAE</option><option value="IN">India</option><option value="PK">Pakistan</option><option value="GB">UK</option><option value="US">USA</option><option value="other">Other</option></select></div>' +
                '<div style="margin-bottom:12px"><label style="font-size:11px;color:#888;display:block">E-mail ID</label><input type="email" name="sh_' + i + '_email_id" style="width:100%;padding:8px 0;border:none;border-bottom:2px solid #e0e0e0;background:transparent;font-size:14px;outline:none"/></div>' +
                '<div style="margin-bottom:12px"><label style="font-size:11px;color:#888;display:block">Mobile number</label><input type="tel" name="sh_' + i + '_mobile" style="width:100%;padding:8px 0;border:none;border-bottom:2px solid #e0e0e0;background:transparent;font-size:14px;outline:none"/></div>' +
                '<div style="display:grid;grid-template-columns:1fr 1fr;gap:16px;margin-bottom:12px">' +
                '<div><label style="font-size:11px;color:#888;display:block">Shares (%)</label><input type="number" name="sh_' + i + '_shares" style="width:100%;padding:8px 0;border:none;border-bottom:2px solid #e0e0e0;background:transparent;font-size:14px;outline:none"/></div>' +
                '<div><label style="font-size:11px;color:#888;display:block">Share value (AED)</label><input type="number" name="sh_' + i + '_share_value" style="width:100%;padding:8px 0;border:none;border-bottom:2px solid #e0e0e0;background:transparent;font-size:14px;outline:none"/></div></div>' +
                '<div style="text-align:right;margin-top:16px"><button type="button" onclick="saveShareholder(' + i + ')" class="save-btn">SAVE</button></div>' +
                '</div></div>';
            list.appendChild(div);
        }
    } else if(count<existing){
        for(var j=existing;j>count;j--){
            var el=document.getElementById('acc_'+j);
            if(el)el.remove();
        }
    }
}
